using System;
using System.Diagnostics;
using System.IO;

namespace EaxReverbEngine
{
    // ملف المساعدة الاصلي (EAX.chm) محفوظ Base64 داخل الكود، بنفس طريقة Assets.cs مع الصور -
    // عشان المستخدم ما يحتاج يرفع/ينقل ملف ثاني لحاله جنب الـ DLL. اول ما يضغط علامة الاستفهام
    // نفكه لملف مؤقت ونفتحه بمشغل المساعدة الافتراضي بويندوز (hh.exe)
    internal static class HelpFile
    {
        private static string _extractedPath;

        public static void Open()
        {
            try
            {
                string path = Extract();
                if (path != null)
                    Process.Start(new ProcessStartInfo(path) { UseShellExecute = true });
            }
            catch (Exception ex) { Log.Write("help: " + ex); }
        }

        private static string Extract()
        {
            if (_extractedPath != null && File.Exists(_extractedPath)) return _extractedPath;
            try
            {
                string dir = Path.Combine(Path.GetTempPath(), "EaxReverbEngine");
                Directory.CreateDirectory(dir);
                string path = Path.Combine(dir, "EAX.chm");
                byte[] bytes = Convert.FromBase64String(Base64);
                if (!File.Exists(path) || new FileInfo(path).Length != bytes.Length)
                    File.WriteAllBytes(path, bytes);
                _extractedPath = path;
                return path;
            }
            catch (Exception ex) { Log.Write("help extract: " + ex); return null; }
        }

        private static readonly string Base64 =
            "";
    }
}
